describe('Data Refresh After Mutation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should automatically refresh data after successful mutation', () => {
    // Intercept the initial API call
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify initial data is displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);

    // Perform mutation (e.g., update a record)
    cy.get('[data-testid="update-button"]').click();
    cy.get('[data-testid="update-form"]').within(() => {
      cy.get('[data-testid="name-input"]').type('New Name');
      cy.get('[data-testid="email-input"]').type('newemail@example.com');
      cy.get('[data-testid="submit-button"]').click();
    });

    // Verify mutation was successful
    cy.get('[data-testid="mutation-success-message"]').should('be.visible');
    cy.get('[data-testid="mutation-success-message"]').should('contain', 'Record updated successfully');

    // Wait for data refresh
    cy.intercept('GET', '/api/data').as('refreshData');
    cy.wait('@refreshData');

    // Verify data is refreshed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="data-row"]').first().should('contain', 'New Name');

    // Verify success message is cleared
    cy.get('[data-testid="mutation-success-message"]').should('not.exist');
  });

  it('should handle failed mutation and display error without refreshing data', () => {
    // Intercept the initial API call
    cy.intercept('GET', '/api/data').as('initialData');
    cy.wait('@initialData');

    // Verify initial data is displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);

    // Perform mutation with invalid data
    cy.get('[data-testid="update-button"]').click();
    cy.get('[data-testid="update-form"]').within(() => {
      cy.get('[data-testid="name-input"]').type('Invalid Name');
      cy.get('[data-testid="email-input"]').type('invalid-email');
      cy.get('[data-testid="submit-button"]').click();
    });

    // Verify mutation was attempted
    cy.get('[data-testid="mutation-error-message"]').should('be.visible');
    cy.get('[data-testid="mutation-error-message"]').should('contain', 'Validation failed');

    // Verify data is still displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length.greaterThan', 0);

    // Verify error message is displayed
    cy.get('[data-testid="mutation-error-message"]').should('contain', 'Validation failed');

    // Verify success message is not displayed
    cy.get('[data-testid="mutation-success-message"]').should('not.exist');
  });
});
